mapper.select:
select wmm.* from wms_move_material wmm left join wms_move_material_detail wmmd on wmm.id = wmmd.move_material_id left join contract_project p on p.id = wmmd.project_id left join mes_building_factory mbf on wmmd.source_factory_id = mbf.id left join mes_building_factory mbf1 on wmmd.direction_factory_id = mbf1.id left join wms_warehouse ww on wmmd.source_warehouse_id = ww.id left join wms_warehouse ww1 on wmm.direction_warehouse_id = ww1.id where wmm.bool_delete_enum = 0
and wmm.bool_party_a = #{boolPartyA}
and wmm.basic_class & #{basicClass} > 0
and wmm.create_time >= #{startAndEndTime[0]}
and wmm.create_time <= #{startAndEndTime[1]}
and wmmd.project_id in
#{projectId}
and wmmd.source_workshop_id in
#{sourceWorkshopId}
and wmmd.source_warehouse_id in
#{sourceWarehouseId}
and wmmd.direction_workshop_id in
#{directionWorkshopId}
and wmmd.direction_warehouse_id in
#{directionWarehouseId}
and wmm.serial_number like CONCAT('%', #{serialNumber},'%')
and ( wmm.applicant_name like CONCAT('%', #{operatorName},'%') or wmm.reviewer_names like CONCAT('%', #{operatorName},'%') )
and wmm.review_status = #{reviewStatus}
group by wmm.id
